#include "shell/paged_list_cache.hpp"
#include "support/check.hpp"
#include <stdexcept>
int main(){namespace t=squiflow::testing;using namespace squiflow::shell;PagedListCache c;auto old=c.begin_query();t::check(c.apply(old,{{"1","one",""}}),"first page applies");c.select("1");t::check(c.selected()=="1","stable id selected");auto current=c.begin_query();t::check(!c.apply(old,{}),"obsolete page rejected");for(int page=0;page<4;++page){std::vector<RowInput> rows;for(int i=0;i<100;++i)rows.push_back({std::to_string(page*100+i),"row","detail"});t::check(c.apply(current,std::move(rows)),"bounded page applies");}t::check(c.page_count()==3&&c.row_count()==300,"old pages evicted at bound");try{c.apply(current,std::vector<RowInput>(101,{"x","x",""}));t::check(false,"oversize rejected");}catch(const std::length_error&){t::check(true,"oversize rejected");}try{c.apply(current,{{"399","duplicate",""}});t::check(false,"duplicate rejected");}catch(const std::invalid_argument&){t::check(true,"duplicate rejected");}return t::report();}
